import { buildApp } from './app.js';

// .env를 프로세스 환경으로 올린다(없으면 무시).
try {
  process.loadEnvFile();
} catch {
  // .env 파일이 없는 환경에서는 실제 환경변수를 그대로 사용한다.
}

const port = Number(process.env.PORT ?? 3000);
const host = '0.0.0.0';

const app = buildApp();

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    app.close().then(
      () => process.exit(0),
      () => process.exit(1),
    );
  });
}

try {
  await app.listen({ port, host });
} catch (err) {
  console.error(err);
  process.exit(1);
}

