import jwt from 'jsonwebtoken';

const EXPIRES_IN = '30d';

/**
 * 시크릿은 최초 사용 시점에 읽는다. server.ts가 `process.loadEnvFile()`를
 * 실행하기 전에 import 그래프가 먼저 평가되므로, 모듈 최상위에서 읽으면
 * .env의 JWT_SECRET을 놓친다.
 */
function secret(): string {
  const value = process.env.JWT_SECRET;
  if (!value) {
    throw new Error('JWT_SECRET 환경변수가 설정되지 않았습니다. .env를 확인하세요.');
  }
  return value;
}

export function signToken(userId: number): string {
  return jwt.sign({ sub: String(userId) }, secret(), {
    algorithm: 'HS256',
    expiresIn: EXPIRES_IN,
  });
}

/** 서명 실패·만료·형식 오류를 모두 null로 흡수한다(throw 금지). */
export function verifyToken(token: string): number | null {
  let payload: string | jwt.JwtPayload;
  try {
    payload = jwt.verify(token, secret(), { algorithms: ['HS256'] });
  } catch {
    return null;
  }

  if (typeof payload === 'string' || typeof payload.sub !== 'string') return null;

  const userId = Number(payload.sub);
  return Number.isInteger(userId) ? userId : null;
}

