import argon2 from 'argon2';

import { ApiError } from '../errors.js';

const MIN_LENGTH = 8;

/**
 * NIST SP 800-63B 기준: 최소 8자, 상한 없음(64자 이상 반드시 허용),
 * 문자 조합 규칙 없음.
 */
export function validatePasswordPolicy(password: unknown): void {
  if (typeof password !== 'string' || password === '') {
    throw ApiError.blank('password');
  }
  if (password.length < MIN_LENGTH) {
    throw ApiError.unprocessable({
      password: [`is too short (minimum is ${MIN_LENGTH} characters)`],
    });
  }
}

/** bcrypt의 72바이트 절단이 64자 이상 정책과 충돌하므로 argon2를 쓴다. */
export async function hashPassword(plain: string): Promise<string> {
  return argon2.hash(plain);
}

export async function verifyPassword(hash: string, plain: string): Promise<boolean> {
  try {
    return await argon2.verify(hash, plain);
  } catch {
    // 손상된 해시 문자열 등: 인증 실패로 취급한다.
    return false;
  }
}

